INSERT INTO "faq" VALUES ('faq-1', 0, '{"q":"Quelles sont les conditions d’admission en BTS ?","r":"Être titulaire du baccalauréat (toutes séries) ou d’un diplôme équivalent. L’admission se fait sur étude du dossier et entretien.","categorie":"Admission","id":"faq-1","etablissementId":"*"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "faq" VALUES ('faq-2', 1, '{"q":"Peut-on s’inscrire en cours du soir en travaillant ?","r":"Oui, les cours du soir ont lieu du lundi au vendredi de 17 h 30 à 20 h 30, et le samedi matin.","categorie":"Formation","id":"faq-2","etablissementId":"*"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "faq" VALUES ('faq-3', 2, '{"q":"Les frais peuvent-ils être payés en plusieurs fois ?","r":"Oui : en 1 fois (–5 %), en 2 tranches ou mensuellement. Paiement par Mobile Money accepté.","categorie":"Frais et paiement","id":"faq-3","etablissementId":"*"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "faq" VALUES ('faq-4', 3, '{"q":"Le diplôme est-il reconnu par l’État ?","r":"Oui, nos BTS et licences sont délivrés sous la tutelle du MINESUP.","categorie":"Diplômes","id":"faq-4","etablissementId":"*"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "faq" VALUES ('faq-5', 4, '{"q":"Quand a lieu la rentrée ?","r":"La rentrée principale a lieu début octobre ; une rentrée décalée est possible en janvier pour certaines filières.","categorie":"Admission","id":"faq-5","etablissementId":"*"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "faq" VALUES ('faq-6', 5, '{"q":"Les stages sont-ils obligatoires ?","r":"Oui, un stage de 2 à 3 mois est obligatoire en fin de première et de deuxième année.","categorie":"Formation","id":"faq-6","etablissementId":"*"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
