INSERT INTO "publications" VALUES ('pub-orientation-bac', 0, '{"id":"pub-orientation-bac","auteurType":"expert","auteurId":"expert-ngono","texte":"Après le bac : BTS, licence ou formation professionnelle ?\nAvant de choisir, regardez trois choses : les débouchés réels de la filière dans votre région, le taux d''insertion des anciens élèves et les frais sur toute la durée, pas seulement la première année. Les fiches des établissements sur YIBOLO donnent déjà une bonne partie de ces informations.","domaines":["education"],"sujets":["orientation","bac"],"image":"/images/maquette/actu-filiere.jpg","publieeLe":"2026-11-24T07:40:00.000Z","jaimes":48,"commentaires":0,"lectures":612,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-sarl', 1, '{"id":"pub-sarl","auteurType":"expert","auteurId":"expert-mbarga","texte":"Créer sa SARL au Cameroun en 2026 : les cinq pièces qu''on oublie le plus souvent.\n\n1. Le plan de localisation du siège, signé.\n2. L''attestation de non-condamnation de chaque gérant.\n3. La déclaration de souscription et de versement.\n4. Les statuts paraphés à chaque page.\n5. La copie de la CNI de chaque associé, certifiée conforme.\n\nUn dossier complet au CFCE, c''est une immatriculation en 72 heures au lieu de trois semaines.","domaines":["conseil-juridique","gestion-d-entreprise"],"sujets":["creation-entreprise","sarl","ohada"],"image":"/images/maquette/pro-banniere-batiment.jpg","publieeLe":"2026-11-23T16:10:00.000Z","jaimes":126,"commentaires":0,"lectures":1840,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-recours-marches', 2, '{"id":"pub-recours-marches","auteurType":"expert","auteurId":"expert-nkoulou","texte":"Marchés publics : votre offre a été écartée pour « pièce manquante » ? Vous disposez d''un recours devant l''Autorité chargée des marchés publics, mais le délai est court. Nous accompagnons les PME dans la rédaction du recours, de l''analyse du rapport d''évaluation à la saisine.","domaines":["marches-publics","conseil-juridique"],"sujets":["marches-publics","recours"],"publieeLe":"2026-11-23T09:25:00.000Z","jaimes":87,"commentaires":0,"lectures":1215,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-licenciement', 3, '{"id":"pub-licenciement","auteurType":"expert","auteurId":"expert-mballa","texte":"Licenciement économique : l''inspection du travail doit être informée AVANT. Beaucoup d''employeurs l''apprennent devant le juge. Si votre entreprise traverse une période difficile, faisons le point sur la procédure avant de prendre une décision.","domaines":["ressources-humaines","conseil-juridique"],"sujets":["droit-du-travail","licenciement"],"publieeLe":"2026-11-22T14:00:00.000Z","jaimes":64,"commentaires":0,"lectures":980,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-kribi-foncier', 4, '{"id":"pub-kribi-foncier","auteurType":"expert","auteurId":"expert-ngo-bell","texte":"Kribi se développe vite, et avec le port arrivent les questions foncières. Avant d''acheter un terrain : exigez le titre foncier, vérifiez-le au service des domaines, et méfiez-vous des ventes sur simple attestation coutumière.","domaines":["immobilier","conseil-juridique"],"sujets":["foncier","kribi","immobilier"],"image":"/images/maquette/region-sud.jpg","publieeLe":"2026-11-21T11:30:00.000Z","jaimes":152,"commentaires":0,"lectures":2430,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-reseaux-sociaux', 5, '{"id":"pub-reseaux-sociaux","auteurType":"expert","auteurId":"expert-ebongue","texte":"Votre établissement sur les réseaux sociaux : publiez moins, mais mieux.\nUne photo de vos étudiants en stage parle plus qu''une affiche de rentrée. Montrez les ateliers, les remises de diplômes, les anciens qui ont trouvé un emploi : c''est ce que les parents regardent avant d''inscrire leur enfant.","domaines":["marketing","education"],"sujets":["communication","reseaux-sociaux"],"image":"/images/maquette/actu-ceremonie.jpg","publieeLe":"2026-11-20T18:45:00.000Z","jaimes":73,"commentaires":0,"lectures":1102,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-dsf', 6, '{"id":"pub-dsf","auteurType":"expert","auteurId":"expert-mbarga","texte":"Rappel : la déclaration statistique et fiscale (DSF) de l''exercice clos se dépose avant le 15 mars. Passé ce délai, la pénalité court dès le premier jour. Si vos états financiers ne sont pas prêts, parlons-en maintenant plutôt qu''en mars.","domaines":["fiscalite","comptabilite"],"sujets":["fiscalite","dsf","pme"],"publieeLe":"2026-11-19T08:15:00.000Z","jaimes":41,"commentaires":0,"lectures":760,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-appel-offres', 7, '{"id":"pub-appel-offres","auteurType":"expert","auteurId":"expert-fotso","texte":"Appel d''offres : trois erreurs qui éliminent une offre avant même l''analyse technique — la caution de soumission absente, une attestation de non-faillite périmée, et une offre financière non signée. Relisez la liste des pièces la veille du dépôt.","domaines":["marches-publics"],"sujets":["marches-publics","appel-d-offres"],"publieeLe":"2026-11-18T10:05:00.000Z","jaimes":58,"commentaires":0,"lectures":890,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-agrement-pme', 8, '{"id":"pub-agrement-pme","auteurType":"expert","auteurId":"expert-nkoulou","texte":"Bonne nouvelle pour nos clients du secteur agroalimentaire : trois dossiers d''agrément au régime des PME ont abouti ce trimestre. Merci à toute l''équipe, et aux entrepreneurs qui nous ont fait confiance.","domaines":["agriculture","gestion-d-entreprise"],"sujets":["pme","agrement"],"image":"/images/maquette/reco-metier.jpg","publieeLe":"2026-11-16T15:20:00.000Z","jaimes":95,"commentaires":0,"lectures":1320,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-cdd', 9, '{"id":"pub-cdd","auteurType":"expert","auteurId":"expert-mballa","texte":"Le contrat à durée déterminée ne se renouvelle pas indéfiniment : au-delà de deux ans, il devient un CDI. Un point à vérifier dans vos contrats en cours.","domaines":["ressources-humaines"],"sujets":["droit-du-travail","cdd"],"publieeLe":"2026-11-14T09:00:00.000Z","jaimes":37,"commentaires":0,"lectures":640,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-bafoussam', 10, '{"id":"pub-bafoussam","auteurType":"expert","auteurId":"expert-fotso","texte":"Bafoussam, Dschang, Mbouda : nous recevons désormais aussi en présentiel le jeudi, sur rendez-vous. Les consultations en ligne restent possibles toute la semaine.","domaines":["fiscalite","comptabilite"],"sujets":["bafoussam","consultation"],"image":"/images/maquette/region-ouest.jpg","publieeLe":"2026-11-12T13:40:00.000Z","jaimes":29,"commentaires":0,"lectures":410,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-whatsapp', 11, '{"id":"pub-whatsapp","auteurType":"expert","auteurId":"expert-mbarga","texte":"Une question revient souvent : un contrat signé par WhatsApp a-t-il une valeur ? Oui, l''Acte uniforme OHADA admet l''écrit électronique — à condition de pouvoir prouver qui a signé, et quand. Gardez les échanges, et confirmez toujours par un courriel récapitulatif.","domaines":["conseil-juridique","informatique"],"sujets":["contrats","ohada"],"publieeLe":"2026-11-10T17:30:00.000Z","jaimes":112,"commentaires":0,"lectures":1980,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-atelier-reglement', 12, '{"id":"pub-atelier-reglement","auteurType":"expert","auteurId":"expert-mballa","texte":"Merci à la Chambre de commerce de Yaoundé pour l''atelier de mardi sur le règlement intérieur. Les supports sont disponibles sur demande.","domaines":["ressources-humaines","gestion-d-entreprise"],"sujets":["atelier","yaounde"],"image":"/images/maquette/actu-rentree.jpg","publieeLe":"2026-11-08T12:00:00.000Z","jaimes":44,"commentaires":0,"lectures":520,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-recouvrement', 13, '{"id":"pub-recouvrement","auteurType":"expert","auteurId":"expert-nkoulou","texte":"Recouvrement de créances : avant de saisir le tribunal, l''injonction de payer OHADA est souvent plus rapide et moins coûteuse. Il faut une créance certaine, liquide et exigible — et des factures en règle.","domaines":["conseil-juridique","finance"],"sujets":["recouvrement","ohada"],"publieeLe":"2026-11-05T10:10:00.000Z","jaimes":52,"commentaires":0,"lectures":870,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
INSERT INTO "publications" VALUES ('pub-succession', 14, '{"id":"pub-succession","auteurType":"expert","auteurId":"expert-ngo-bell","texte":"Succession sans testament : la loi désigne les héritiers, mais le partage peut prendre des années faute d''accord. Un testament authentique chez le notaire évite bien des conflits familiaux.","domaines":["immobilier","conseil-juridique"],"sujets":["succession","famille"],"publieeLe":"2026-11-02T08:30:00.000Z","jaimes":68,"commentaires":0,"lectures":1150,"statut":"publiee"}', '2026-11-24T00:00:00.000Z', '2026-11-24T00:00:00.000Z');
